def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    for comp in components(g != bg):
        cols = sorted(set(int(g[y, x]) for y, x in comp))
        if len(cols) == 2:
            a, b = cols
            for y, x in comp:
                out[y, x] = b if g[y, x] == a else a
            emit(out.copy(), f"Swap colours {a} and {b} inside the block at {bbox(comp)}.")
    emit(out.copy(), "All two-colour blocks have their colours exchanged.")
    return out
